#!/usr/bin/env python3
"""Chapter 13: finite uniform completeness and integration checks."""
from __future__ import annotations
from pathlib import Path
from itertools import combinations
import json
import re

ROOT = Path(__file__).resolve().parents[2]
CH = "chapters/pl/general_topology/13-zupelnosc-jednostajna-i-uzupelnienia.tex"
STANDALONE = "books/pl/general_topology_ch13.tex"
BOOK = "books/pl/general_topology.tex"

def finite_partition_checks():
    # Every uniformity on a finite set is generated by an equivalence relation.
    # A Cauchy filter on a finite set is principal: it is generated by a
    # nonempty set A (the intersection of all its members).
    total = 0
    for n in range(5):
        for labels in __import__("itertools").product(range(n), repeat=n):
            if n and (labels[0] != 0 or
                      sorted(set(labels)) != list(range(max(labels) + 1))):
                continue
            if n == 0 and labels != ():
                continue
            if not n:
                total += 1
                continue
            blocks = [{i for i, c in enumerate(labels) if c == k}
                      for k in sorted(set(labels))]
            equiv = {(i, j) for B in blocks for i in B for j in B}
            for mask in range(1, 1 << n):
                A = {i for i in range(n) if mask & (1 << i)}
                # Cauchy iff all pairs of A lie in the minimum entourage.
                cauchy = all((i, j) in equiv for i in A for j in A)
                if cauchy:
                    # The principal filter on A converges to each point
                    # whose equivalence class contains A.
                    assert any(all((x, a) in equiv for a in A)
                               for x in range(n))
            total += 1
    assert total > 0
    return total

def lint():
    source = (ROOT / CH).read_text(encoding="utf-8")
    assert (ROOT / STANDALONE).is_file()
    assert r"\input{../../" + CH + "}" in (ROOT / BOOK).read_text(encoding="utf-8")
    assert r"\input{../../" + CH + "}" in (ROOT / STANDALONE).read_text(encoding="utf-8")
    entry = next(b for b in json.loads((ROOT / "catalog/books.json").read_text())["books"]
                 if b["id"] == "general_topology")
    assert entry["chapters"][-1] == CH
    labels, refs = [], []
    for p in entry["chapters"]:
        text = (ROOT / p).read_text(encoding="utf-8")
        labels.extend(re.findall(r"\\label\{([^}]+)\}", text))
        refs.extend(re.findall(r"\\(?:ref|eqref|pageref)\{([^}]+)\}", text))
        assert not re.search(r"zwartościowani\w*|zbieżności\s+zwartej", text, re.I)
    assert len(labels) == len(set(labels)), "duplicate labels"
    assert set(refs) <= set(labels), f"missing labels: {set(refs)-set(labels)}"
    for env in ("twierdzenie","lemat","stwierdzenie","wniosek","definicja",
                "przyklad","uwaga","proof"):
        assert source.count(r"\begin{" + env + "}") == source.count(
            r"\end{" + env + "}"), env
    assert r"\label{thm:topog-uzupelnienia-istnienie}" in source
    assert r"\label{thm:topog-uzupelnienia-uniwersalnosc}" in source
    return len(labels),len(refs)

if __name__ == "__main__":
    n=finite_partition_checks()
    l,r=lint()
    print(f"PASS chapter 13 finite uniformities={n}, labels={l}, refs={r}")
